function deskSetting(key, fallback) {
  try {
    const s = $('Fetch desk settings').first().json || {};
    const v = s[key];
    if (v != null && String(v).trim() !== '') return String(v).trim();
  } catch (e) {}
  return fallback;
}
const ORG_ID = deskSetting('zoho.organization_id', '939049468');
const PAID_THROUGH = deskSetting('zoho.paid_through_account_id', '1300646000000000361');
const DEFAULT_EXPENSE = deskSetting('zoho.default_expense_account_id', '1300646000000000460');
const TZ = deskSetting('company.timezone', 'Africa/Lagos');
const ACCOUNTS = [
  { id: '1300646000000000400', keys: ['office supplies', 'stationery', 'printer', 'paper'] },
  { id: '1300646000000000403', keys: ['advertis', 'marketing', 'ads', 'boost'] },
  { id: '1300646000000032023', keys: ['lodging', 'hotel', 'airbnb', 'accommodation'] },
  { id: DEFAULT_EXPENSE, keys: ['other expenses', 'other', 'misc'] },
  { id: '1300646000000035005', keys: ['uncategor'] },
];
function pickAccount(sd) {
  const hay = [sd.zoho_account_name, sd.account_name, sd.category, sd.vendor, sd.vendor_name, sd.description]
    .filter(Boolean).join(' ').toLowerCase();
  for (const row of ACCOUNTS) {
    if (row.keys.some((k) => hay.includes(k))) return row.id;
  }
  return DEFAULT_EXPENSE;
}
function lagosDate(raw) {
  if (raw && /^\d{4}-\d{2}-\d{2}/.test(String(raw))) return String(raw).slice(0, 10);
  return new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(new Date());
}
const j = $('When executed by another workflow').first().json || {};
const sd = j.structured_data || j;
const action = String(j.action || sd.zoho_action || '').toLowerCase();
const amount = Number(j.amount ?? sd.amount ?? sd.base_amount);
const allowed = ['expense', 'bill', 'invoice', 'lookup', 'preview'];
if (!allowed.includes(action)) {
  return [{ json: { skip: true, action: 'none', audit_text: 'Zoho Books: nothing to do.' } }];
}
const vendor = String(j.vendor_name || sd.vendor_name || sd.vendor || '').trim();
const customer = String(j.customer_name || sd.customer_name || '').trim() || vendor;
return [{ json: {
  skip: false,
  action,
  amount: Number.isFinite(amount) ? amount : 0,
  currency: String(j.currency || sd.currency || 'NGN').toUpperCase(),
  vendor_name: vendor,
  customer_name: customer,
  customer_email: (function () {
    const raw = String(j.email || j.customer_email || sd.email || sd.customer_email || '').trim().toLowerCase();
    if (!raw || raw.indexOf('@') < 1 || raw.indexOf('.') < 0 || /\s/.test(raw)) return '';
    return raw.slice(0, 200);
  })(),
  date: lagosDate(j.date || sd.date),
  description: String(j.description || sd.notes || sd.expense_description || vendor || 'Ops').slice(0, 200),
  account_id: pickAccount(Object.assign({}, sd, j)),
  paid_through_account_id: PAID_THROUGH,
  is_taxable: j.is_taxable_service === true || sd.is_taxable_service === true,
  is_professional: j.is_professional_service === true || sd.is_professional_service === true,
  reference: String(j.reference || sd.reference || sd.reference_number || '').trim().slice(0, 100),
  lookup: String(j.lookup || sd.lookup || 'overview'),
  organization_id: ORG_ID,
  timezone: TZ
} }];

const p = $('Normalize').item.json;
if (p.skip) return [{ json: p }];
const taxes = ($input.first().json || {}).taxes || [];
function scoreVAT(t) {
  const n = String(t.tax_name || '').toLowerCase();
  let s = 0;
  if (n.includes('withhold') || n.includes('wht') || n.includes('tds')) s -= 5;
  if (n.includes('vat')) s += 4;
  if (Number(t.tax_percentage) === 7.5) s += 3;
  if (Number(t.tax_percentage) > 0) s += 1;
  return s;
}
const ranked = taxes.slice().sort((a, b) => scoreVAT(b) - scoreVAT(a));
const vat = p.is_taxable ? (ranked[0] && scoreVAT(ranked[0]) > 0 ? ranked[0] : null) : null;
return [{ json: {
  ...p,
  taxes,
  tax_id: vat ? String(vat.tax_id) : '',
  tax_name: vat ? String(vat.tax_name) : '',
  tax_percentage: vat ? Number(vat.tax_percentage) : 0
} }];

function money(n) {
  const x = Number(n);
  if (!Number.isFinite(x)) return '—';
  return 'NGN ' + x.toFixed(2);
}
function names(list, nameKey, extra) {
  if (!Array.isArray(list) || !list.length) return '  (none)';
  return list.slice(0, 5).map((row) => {
    const n = row[nameKey] || row.vendor_name || row.customer_name || '';
    const amt = row.balance ?? row.total ?? row.amount;
    const extraBit = extra ? extra(row) : '';
    return '  - ' + n + ' ' + money(amt) + extraBit;
  }).join('\n');
}
const p = $('Attach tax').item.json;
const inv = $('GET unpaid invoices').item.json || {};
const bills = $('GET unpaid bills').item.json || {};
const exps = $('GET recent expenses').item.json || {};
const pnl = $('GET cash P&L').item.json || {};
const year = new Date().getFullYear();
const lines = ['Zoho Books snapshot (live API, not LLM)'];
if (inv.code && inv.code !== 0) lines.push('Invoices: ' + inv.message);
else {
  const list = inv.invoices || [];
  lines.push('Unpaid invoices (' + list.length + ' on this page):');
  lines.push(names(list, 'customer_name', (r) => r.invoice_number ? ' ' + r.invoice_number : ''));
}
if (bills.code && bills.code !== 0) lines.push('Bills: ' + bills.message);
else {
  const list = bills.bills || [];
  lines.push('Unpaid bills (' + list.length + ' on this page):');
  lines.push(names(list, 'vendor_name', (r) => r.bill_number ? ' ' + r.bill_number : ''));
}
if (exps.code && exps.code !== 0) lines.push('Expenses: ' + exps.message);
else {
  const list = exps.expenses || [];
  lines.push('Recent expenses:');
  lines.push(names(list, 'account_name', (r) => r.date ? ' ' + r.date : ''));
}
const groups = pnl.profit_and_loss || pnl.profitandloss || [];
if (pnl.code && pnl.code !== 0) {
  lines.push('P&L: ' + pnl.message);
} else if (Array.isArray(groups) && groups.length) {
  lines.push('Cash P&L ' + year + ' YTD:');
  for (const g of groups.slice(0, 8)) {
    lines.push('  ' + (g.name || g.account_name || 'line') + ': ' + money(g.total ?? g.amount));
  }
} else if (pnl.total_income != null || pnl.net_profit != null) {
  lines.push('Cash P&L ' + year + ' YTD: income ' + money(pnl.total_income) + ' · net ' + money(pnl.net_profit));
}
lines.push('Tax table in Books: ' + (p.taxes || []).map((t) => t.tax_name + ' ' + t.tax_percentage + '%').join(', ') || '(none — add VAT in Settings)');
return [{ json: { kind: 'lookup', audit_text: lines.join('\n') } }];

const p = $input.first().json;
const rate = Number(p.tax_percentage) || 0;
const vat = Math.round(p.amount * rate) / 100;
const lines = [
  'Zoho Books preview (not posted)',
  'Base: NGN ' + Number(p.amount).toFixed(2),
];
if (p.tax_id) {
  lines.push('VAT from Books Settings: ' + p.tax_name + ' ' + rate + '% = NGN ' + vat.toFixed(2));
  lines.push('Gross if posted exclusive: NGN ' + (p.amount + vat).toFixed(2));
} else {
  lines.push('No VAT tax_id in Books Settings — add VAT under Settings → Taxes so posts can carry tax.');
}
if (p.is_professional) {
  lines.push('Professional fee: withhold WHT when recording the vendor payment in Books. Not a second ledger here.');
}
return [{ json: { kind: 'preview', audit_text: lines.join('\n'), tax_name: p.tax_name, tax_percentage: rate } }];

const p = $('Attach tax').item.json;
const res = $input.first().json || {};
const exp = res.expense || {};
if (res.code && res.code !== 0 && !exp.expense_id) {
  return [{ json: { kind: 'error', audit_text: 'Zoho Books expense: ' + String(res.message || JSON.stringify(res)).slice(0, 400), code: res.code, message: res.message } }];
}
const taxAmt = Number(exp.tax_amount || exp.tax_total || 0);
const total = Number(exp.total || exp.amount || p.amount);
const lines = [
  'Recorded in Zoho Books as expense ' + (exp.expense_id || '') + (exp.expense_number ? ' (' + exp.expense_number + ')' : ''),
  'Base NGN ' + Number(p.amount).toFixed(2) + (p.tax_name ? ' + ' + p.tax_name + ' NGN ' + taxAmt.toFixed(2) : ' (no tax_id)'),
  'Books total NGN ' + total.toFixed(2),
];
if (p.is_professional) lines.push('If WHT applies, withhold it on the vendor payment in Books.');
return [{ json: { kind: 'expense', audit_text: lines.join('\n'), expense: exp, code: res.code, message: res.message } }];

const p = $('Attach tax').item.json;
const res = $input.first().json || {};
const list = Array.isArray(res.contacts) ? res.contacts : [];
const name = p.vendor_name.toLowerCase();
let hit = list.find((c) => String(c.contact_name || '').toLowerCase() === name) || list[0];
if (hit && hit.contact_id) {
  return [{ json: { ...p, mode: 'use', vendor_id: String(hit.contact_id), vendor_existing: hit.contact_name } }];
}
return [{ json: { ...p, mode: 'create', body: { contact_name: p.vendor_name.slice(0, 200), contact_type: 'vendor' } } }];

const p = $('Ensure vendor').item.json;
const res = $input.first().json || {};
const id = (res.contact && res.contact.contact_id) || res.contact_id || p.vendor_id;
if (!id) {
  return [{ json: { kind: 'error', audit_text: 'Zoho Books: could not create vendor. ' + String(res.message || JSON.stringify(res)).slice(0, 300), code: res.code, message: res.message } }];
}
return [{ json: { ...p, vendor_id: String(id) } }];

const p = $('Ensure vendor').item.json;
const res = $input.first().json || {};
const bill = res.bill || {};
if (res.code && res.code !== 0 && !bill.bill_id) {
  return [{ json: { kind: 'error', audit_text: 'Zoho Books bill: ' + String(res.message || JSON.stringify(res)).slice(0, 400), code: res.code, message: res.message } }];
}
const taxAmt = Number((bill.taxes && bill.taxes[0] && bill.taxes[0].tax_amount) || bill.tax_total || 0);
const lines = [
  'Recorded in Zoho Books as bill ' + (bill.bill_id || '') + (bill.bill_number ? ' (' + bill.bill_number + ')' : ''),
  'Vendor ' + (p.vendor_name || '') + ' · due NGN ' + Number(bill.balance || bill.total || p.amount).toFixed(2),
];
if (p.tax_name) lines.push('VAT from Books: ' + p.tax_name + (taxAmt ? ' NGN ' + taxAmt.toFixed(2) : ''));
if (p.is_professional) lines.push('Unpaid. Withhold WHT when you record the vendor payment in Books — do not duplicate WHT as an expense.');
else lines.push('Unpaid. Pay it in Books when cash leaves.');
return [{ json: { kind: 'bill', audit_text: lines.join('\n'), bill, code: res.code, message: res.message } }];

const p = $('Attach tax').item.json;
const res = $input.first().json || {};
const list = Array.isArray(res.contacts) ? res.contacts : [];
const name = p.customer_name.toLowerCase();
let hit = list.find((c) => String(c.contact_name || '').toLowerCase() === name) || list[0];
if (hit && hit.contact_id) {
  return [{ json: { ...p, mode: 'use', customer_id: String(hit.contact_id) } }];
}
const body = { contact_name: p.customer_name.slice(0, 200), contact_type: 'customer' };
if (p.customer_email) body.contact_persons = [{ email: p.customer_email, is_primary_contact: true }];
return [{ json: { ...p, mode: 'create', body } }];

const p = $('Ensure customer').item.json;
const res = $input.first().json || {};
const id = (res.contact && res.contact.contact_id) || res.contact_id || p.customer_id;
if (!id) {
  return [{ json: { kind: 'error', audit_text: 'Zoho Books: could not create customer. ' + String(res.message || JSON.stringify(res)).slice(0, 300), code: res.code, message: res.message } }];
}
return [{ json: { ...p, customer_id: String(id) } }];

const p = $('Ensure customer').item.json;
const res = $('POST invoice').item.json || {};
const inv = res.invoice || {};
if (res.code && res.code !== 0 && !inv.invoice_id) {
  return [{ json: { kind: 'error', audit_text: 'Zoho Books invoice: ' + String(res.message || JSON.stringify(res)).slice(0, 400), code: res.code, message: res.message } }];
}
const lines = [
  'Invoice in Zoho Books ' + (inv.invoice_number || inv.invoice_id || ''),
  'Customer ' + (p.customer_name || '') + ' · total NGN ' + Number(inv.total || p.amount).toFixed(2) + ' · status ' + (inv.status || 'draft'),
];
if (p.tax_name) lines.push('VAT from Books: ' + p.tax_name);
if (!p.customer_email) lines.push('No customer email — Paystack link skipped.');
return [{ json: {
  kind: 'invoice',
  audit_text: lines.join('\n'),
  invoice: inv,
  customer_email: p.customer_email || '',
  customer_name: p.customer_name || '',
  customer_id: p.customer_id || (inv.customer_id || ''),
  organization_id: p.organization_id,
  description: p.description || '',
  amount: p.amount,
  code: res.code,
  message: res.message
} }];

const j = $input.first().json || {};
if (j.kind === 'error') {
  return [{ json: { ...j, paystack: false } }];
}
const email = String(j.customer_email || '').trim().toLowerCase();
const inv = j.invoice || {};
const naira = Number(inv.total);
const kobo = Number.isFinite(naira) ? Math.round(naira * 100) : 0;
const invoiceId = String(inv.invoice_id || '');
let audit = String(j.audit_text || '');
if (!invoiceId) {
  return [{ json: { ...j, paystack: false } }];
}
if (!email) {
  return [{ json: { ...j, paystack: false, kobo: 0 } }];
}
if (!(kobo > 0)) {
  audit += '\nBooks total was 0 — no Paystack link.';
  return [{ json: { ...j, paystack: false, audit_text: audit, kobo: 0 } }];
}
return [{ json: { ...j, paystack: true, kobo, naira, customer_email: email, zoho_invoice_id: invoiceId } }];

const j = $input.first().json || {};
if (j.paystack) {
  return [{ json: { ...j, audit_text: String(j.audit_text || '') + '\nPAYSTACK_SECRET_KEY is not set on n8n — invoice is in Books only.' } }];
}
return [{ json: j }];

const p = $('Paystack gate').item.json;
const res = $input.first().json || {};
const data = res.data || {};
const code = data.customer_code || '';
if (!code) {
  return [{ json: { ...p, paystack: false, audit_text: String(p.audit_text || '') + '\nPaystack: could not upsert customer. ' + String(res.message || JSON.stringify(res)).slice(0, 200) } }];
}
return [{ json: { ...p, paystack_customer_code: String(code) } }];

const p = $('Stamp Paystack customer').item.json;
const res = $input.first().json || {};
const data = res.data || {};
const code = String(data.request_code || '');
let audit = String(p.audit_text || '');
if (res.status === false || !code) {
  audit += '\nPaystack: could not create payment request. ' + String(res.message || JSON.stringify(res)).slice(0, 200);
  return [{ json: { ...p, audit_text: audit, paystack_request: data } }];
}
const url = 'https://paystack.com/pay/' + code;
audit += '\nPay: ' + url;
audit += '\nPaystack ' + code;
if (data.offline_reference) audit += ' · bank ref ' + data.offline_reference;
return [{ json: { ...p, audit_text: audit, paystack_request: data, paystack_url: url, paystack_request_code: code } }];
